def icloud_delete_row(value):
    row=[part.strip() for part in value.split('¦')]
    assert len(row)==len(ICLOUD_DELETE_KEYS), (len(row), len(ICLOUD_DELETE_KEYS))
    return dict(zip(ICLOUD_DELETE_KEYS,row))

